import { existsSync } from 'node:fs';
import { defineConfig } from 'prisma/config';

// Local development reads packages/database/.env (generated by `pnpm bootstrap`;
// Prisma CLI commands run in this package). Real environment variables always
// take precedence (CI, staging, production).
if (existsSync('.env')) process.loadEnvFile('.env');

export default defineConfig({
  schema: 'prisma/schema.prisma',
  migrations: { path: 'prisma/migrations' },
  // Not required for `prisma generate`; migrate commands fail clearly without it.
  datasource: process.env.DATABASE_URL === undefined ? {} : { url: process.env.DATABASE_URL },
});
